/* -*- coding: utf-8; tab-width: 4 -*- */

#include <cstdio>
#include <vector>
#include <array>
#include <algorithm>

int main()
{
	int n, l, r, x, c, k, h(0), t;
	std::vector<std::array<int, 3>> v;

	std::scanf("%d%d%d%d", &n, &l, &r, &x);
	for (int i(0); i < n; ++i) {
		std::scanf("%d", &c);
		k = v.size();
		v.push_back({{c, c, c}});
		for (int j(0); j < k; ++j) {
			v.push_back({{
				v[j][0] + c,
				std::min(v[j][1], c),
				std::max(v[j][2], c)
			}});
		}
	}

	for (int i(0); i < static_cast<int>(v.size()); ++i) {
		if (v[i][2] - v[i][1] < x) {
			v[i][0] = 0;
		}
	}
	std::stable_sort(v.begin(), v.end());

	while (h < static_cast<int>(v.size()) && v[h][0] < l) {
		++h;
	}
	t = h;
	while (t < static_cast<int>(v.size()) && v[t][0] <= r) {
		++t;
	}

	std::printf("%d\n", t - h);

	return 0;
}

